using Microsoft.AspNetCore.Html;
using Microsoft.AspNetCore.Localization;
using Microsoft.AspNetCore.Mvc.Razor;
using System.Globalization;

namespace [Appiation Name].UserLocalization
{
    public class Localization
    {
        //the hidden input element id which will be dynamically generated by the Localization javascript class
        private const string HiddenCultureFormElement = "_HiddenCulture";
        private const string HttpHeaderAcceptLanguage = "Accept-Language";
        //the Localization javascript class name
        private const string JavascriptClassName = "Localization";
        //List of configured cultures (the first is the default one).
        public static List<CultureInfo> SupportedCultures { get; } = new List<CultureInfo>() {
                new CultureInfo("it"),
                new CultureInfo("en"),
                new CultureInfo("pt"),
        };
        public enum LocationExpanderFormat
        {
            MvcViewSuffix = 1,
            MvcViewSubfolder = 2,
            RazorPages = 3,
        }
        private RequestLocalizationOptions LocalizationOptions = new RequestLocalizationOptions();
        public void AddLocalization(WebApplicationBuilder builder, string ResourcesPath, LocationExpanderFormat lef)
        {
            builder.Services.AddLocalization(options => options.ResourcesPath = ResourcesPath);

            switch (lef)
            {
                case LocationExpanderFormat.MvcViewSuffix:
                    builder.Services.AddMvc().AddViewLocalization(LanguageViewLocationExpanderFormat.Suffix);
                    break;
                case LocationExpanderFormat.MvcViewSubfolder:
                    builder.Services.AddMvc().AddViewLocalization(LanguageViewLocationExpanderFormat.SubFolder);
                    break;
                case LocationExpanderFormat.RazorPages:
                    break;
            }

            LocalizationOptions.DefaultRequestCulture = new RequestCulture(SupportedCultures[0]);
            LocalizationOptions.SupportedCultures = SupportedCultures;
            LocalizationOptions.SupportedUICultures = SupportedCultures;
            LocalizationOptions.RequestCultureProviders = new List<IRequestCultureProvider>
            {
                new QueryStringRequestCultureProvider(),
                new CookieRequestCultureProvider(),
            };
        }
        public void UseRequestLocalization(WebApplication app) { app.UseRequestLocalization(LocalizationOptions); }
        //configuration and registration of the location cookie
        public static void SetCultureInfo(HttpResponse Response, string Culture)
        {
            Response.Cookies.Append(CookieRequestCultureProvider.DefaultCookieName,
                                    CookieRequestCultureProvider.MakeCookieValue(new RequestCulture(Culture)),
                                    new CookieOptions { Expires = DateTimeOffset.UtcNow.AddYears(1) });
            Thread.CurrentThread.CurrentUICulture = new CultureInfo(Culture);
            Thread.CurrentThread.CurrentCulture = new CultureInfo(Culture);
        }
        //change user culture on postback
        public static void SetCultureInfoOnPostBack(HttpContext Context)
        {
            if (Context.Request.Method.ToUpper() == "POST")
            {
                if (Context.Request.Form[HiddenCultureFormElement].ToString() != "")
                {
                    SetCultureInfo(Context.Response, Context.Request.Form[HiddenCultureFormElement].ToString());
                }
            }
        }
        //retrieve the current user interface culture
        public static string CurrentUICulture { get { return Thread.CurrentThread.CurrentUICulture.ToString(); } }
        //Invoked only in the actions of web api controllers
        public static void SetCultureInfoFromHttpHeader(HttpRequest Request)
        {
            var culture = Request.Headers[HttpHeaderAcceptLanguage];
            if (!String.IsNullOrEmpty(culture) && culture.ToString().Length == 2) 
            { 
                Thread.CurrentThread.CurrentUICulture = new CultureInfo(culture.ToString()); 
            }
        }
        //register the javascript Localization class into a razor page.
        public static HtmlString JavascriptRegistration
        {
            get
            {
                return new HtmlString("<script type=\"text/javascript\">new " + JavascriptClassName + "('" + HiddenCultureFormElement + "');</script>");
            }
        }
    }
}
